--- a/Sources/Clinic/VisitListViewModel.swift
+++ b/Sources/Clinic/VisitListViewModel.swift
@@ -9,16 +9,30 @@ final class VisitListViewModel: ObservableObject {

     @Published private(set) var visits: [Visit] = []

     private let api: API
     private let center: NotificationCenter

-    init(api: API, center: NotificationCenter = .default) {
-        self.api = api
-        self.center = center
+    init(api: API, center: NotificationCenter = .default) {
+        self.api = api
+        self.center = center
+
+        center.addObserver(forName: .scheduleChanged, object: nil, queue: .main) { _ in
+            self.reload()
+        }
+    }
+
+    func reload() {
+        Task {
+            visits = (try? await api.visits()) ?? visits
+        }
     }

     deinit {
         center.removeObserver(self)
     }
 }
